        return vimpo_config

    def _validate_vimpo_mode(self):
        vimpo_config = self._get_vimpo_config()
        value_type = str(vimpo_config.get("value_type", "raw"))
        use_grpo_actor = bool(vimpo_config.get("use_grpo_actor", False))
